#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyTypeClass {
    // Top‐level abstract classes
    BooleanType,
    IntegerType,
    FloatingType,
    ComplexType,
    NumberType,
    InexactType,
    ScalarType,
    ObjectType,
    // Integer leaves
    Int8Type,
    Int16Type,
    Int32Type,
    Int64Type,
    UInt8Type,
    UInt16Type,
    UInt32Type,
    UInt64Type,
    // Floating‐point leaves
    Float32Type,
    Float64Type,
    // Complex leaves
    Complex64Type,
    Complex128Type,
}

pub fn issubclass_(arg1: NumpyTypeClass, arg2: NumpyTypeClass) -> bool {
    // Reflexivity
    if arg1 == arg2 {
        return true;
    }

    use NumpyTypeClass::*;
    match (arg1, arg2) {
        // Integer leaves → IntegerType
        (Int8Type  | Int16Type | Int32Type | Int64Type
       | UInt8Type | UInt16Type | UInt32Type | UInt64Type,
         IntegerType) => true,

        // Floating‐point leaves → FloatingType
        (Float32Type | Float64Type,
         FloatingType) => true,

        // Complex leaves → ComplexType
        (Complex64Type | Complex128Type,
         ComplexType) => true,

        // Mid‐level relations
        (IntegerType, NumberType)
        | (FloatingType, InexactType)
        | (FloatingType, NumberType)
        | (ComplexType, InexactType)
        | (ComplexType, NumberType) => true,

        // Top‐level scalar relations
        (NumberType
       | BooleanType
       | IntegerType
       | FloatingType
       | ComplexType
       | InexactType,
         ScalarType) => true,

        // No other direct relations count
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_reflexivity() {
        for ty in &[
            NumpyTypeClass::BooleanType,
            NumpyTypeClass::Int8Type,
            NumpyTypeClass::Float64Type,
            NumpyTypeClass::Complex128Type,
            NumpyTypeClass::NumberType,
            NumpyTypeClass::ScalarType,
            NumpyTypeClass::ObjectType,
        ] {
            assert!(issubclass_(*ty, *ty));
        }
    }

    #[test]
    fn test_integer_leaves() {
        let leaves = &[
            NumpyTypeClass::Int8Type,
            NumpyTypeClass::Int16Type,
            NumpyTypeClass::Int32Type,
            NumpyTypeClass::Int64Type,
            NumpyTypeClass::UInt8Type,
            NumpyTypeClass::UInt16Type,
            NumpyTypeClass::UInt32Type,
            NumpyTypeClass::UInt64Type,
        ];
        for &leaf in leaves {
            assert!(issubclass_(leaf, NumpyTypeClass::IntegerType));
            assert!(!issubclass_(leaf, NumpyTypeClass::NumberType)); // No transitive
        }
    }

    #[test]
    fn test_floating_leaves() {
        let leaves = &[NumpyTypeClass::Float32Type, NumpyTypeClass::Float64Type];
        for &leaf in leaves {
            assert!(issubclass_(leaf, NumpyTypeClass::FloatingType));
            assert!(!issubclass_(leaf, NumpyTypeClass::InexactType));
        }
    }

    #[test]
    fn test_complex_leaves() {
        let leaves = &[NumpyTypeClass::Complex64Type, NumpyTypeClass::Complex128Type];
        for &leaf in leaves {
            assert!(issubclass_(leaf, NumpyTypeClass::ComplexType));
            assert!(!issubclass_(leaf, NumpyTypeClass::NumberType));
        }
    }

    #[test]
    fn test_mid_level() {
        assert!(issubclass_(NumpyTypeClass::IntegerType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::FloatingType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::FloatingType, NumpyTypeClass::InexactType));
        assert!(issubclass_(NumpyTypeClass::ComplexType, NumpyTypeClass::NumberType));
        assert!(issubclass_(NumpyTypeClass::ComplexType, NumpyTypeClass::InexactType));
        // Not transitive
        assert!(!issubclass_(NumpyTypeClass::Int32Type, NumpyTypeClass::NumberType));
    }

    #[test]
    fn test_top_level_scalar() {
        let mids = &[
            NumpyTypeClass::NumberType,
            NumpyTypeClass::BooleanType,
            NumpyTypeClass::IntegerType,
            NumpyTypeClass::FloatingType,
            NumpyTypeClass::ComplexType,
            NumpyTypeClass::InexactType,
        ];
        for &mid in mids {
            assert!(issubclass_(mid, NumpyTypeClass::ScalarType));
        }
        assert!(!issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::ScalarType));
    }

    #[test]
    fn test_object_type() {
        // Only reflexive
        assert!(issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::ObjectType));
        assert!(!issubclass_(NumpyTypeClass::ObjectType, NumpyTypeClass::NumberType));
        assert!(!issubclass_(NumpyTypeClass::Int8Type, NumpyTypeClass::ObjectType));
    }
}